export default NotConnectedSection;

/**
 * RoundsThatCountSection — PHASE 4 "THE MECHANISM" of
 * BRIEF_HANDICAP_TAB_REBUILD (replaces the Section E grammar).
 *
 * Kicker THE MECHANISM, title "Eight of your last twenty", the §4.1 caption,
 * LastTwentyBars (kept: twenty differentials oldest-left, min-anchored scale,
 * counting state from is_counter via countsTowardIndex — never a client-side
 * comparison), the amber cut line at the eighth-best differential, date axis
 * labels, then THE COUNTING EIGHT chip box ending after its chips.
 *
 * WHAT IS GONE, BY CONSTRUCTION:
 *  - The NEXT ROUND / "{target} CUTS" footer strip (Section C owns that).
 *  - The FALLING OFF SOON readout and the generated caption/fall lines:
 *    phase 3's AgeingOutSection owns the expiry warning now.
 *  - Boundary label and NEXT IN LINE row (BRIEF_HANDICAP_TAB_REBUILD_4A).
 *    The amber rule stays; AgeingOutSection owns replacement advice.
 *
 * BRIEF_MECHANISM_PAIRING_2: the selection defaults to the newest round in the
 * twenty, and a tap only selects — this section never opens RoundDetailSheet.
 * The two-line detail block always renders, so the section never moves.
 * NET comes from gam_round_net via useRoundNetScores, blank when absent.
 *
 * NINE HOLES CARRY NO MARK HERE: WHS states every differential on an
 * eighteen-hole basis, so every point is already on one scale.
 */
import { countsTowardIndex, counterWindow } from '@/lib/whs/counting';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';

/* Figures use a TRUE MINUS (U+2212), never a hyphen. */
import { fmtDiff } from '@/lib/whs/format';
import { analyticsEvents } from '@/utils/analyticsEvents';
import { useAllScores } from '@/lib/whs/hooks';
import { formatDayMonthShortGB } from '@/i18n/format';

import { HcpSection } from './HcpSection';
import { CHART } from '../charts';
import LastTwentyBars from '../charts/LastTwentyBars';
import { A } from '@/features/courses/components/holes/analytical/tokens';
import { MEMBER_PANEL, inkWithAlpha } from '@/lib/tokens/surfaces';
import { useRoundNetScores } from '@/components/explore-tab-new/courseled/hooks/useRoundNetScores';

/** A full rolling window. Below this the section states the sample instead. */
const MIN_ROUNDS = 20;

const FIG: React.CSSProperties = {
  fontVariantNumeric: 'tabular-nums lining-nums',
  letterSpacing: '-0.04em',
};

/** Reserved height of the selection slot: 14/600 name row + 16 figure row. */
const SLOT_H = 40;

interface Props {
  connectionId: string;
  userId?: string | null;
}

/** To-par suffix: E, +n, or a true-minus figure. */
const fmtToPar = (n: number) => (n === 0 ? 'E' : n > 0 ? `+${n}` : `\u2212${-n}`);

const RoundsThatCountSection: React.FC<Props> = ({ connectionId, userId = null }) => {
  const { t } = useTranslation(['common']);
  const { data: allScores, isLoading } = useAllScores(connectionId);

  /* BRIEF_MECHANISM_PAIRING: ONE selection, by ROUND ID (never by differential —
     duplicate differentials are real). Bars and chips both read it; it
     persists after the sheet closes; re-tapping re-opens rather than clears. */
  const [selId, setSelId] = useState<string | null>(null);

  const total = allScores?.length ?? 0;

  /**
   * Last 20, OLDEST FIRST. ONE SOURCE FOR THE COUNTER SET: is_counter as it
   * arrives on useAllScores (whs_scores), the same read the posted-history
   * sheet uses.
   */
  const windowBase = useMemo(() => {
    if (!allScores || allScores.length === 0) return [];
    return counterWindow(allScores)
      .sort((a, b) => new Date(a.play_date).getTime() - new Date(b.play_date).getTime())
      .map((r) => ({
        id: r.id,
        play_date: r.play_date,
        diff: r.handicap_differential ?? null,
        is_counter: countsTowardIndex(r),
        course_name: r.course?.name ?? null,
        gross: r.adjusted_gross ?? null,
        par: r.course_par ?? null,
      }));
  }, [allScores]);

  /* ONE batched net read for the whole window, keyed on whs_scores ids. */
  const nets = useRoundNetScores(windowBase.map((r) => r.id));
  const window20 = useMemo(
    () => windowBase.map((r) => ({ ...r, net: nets.get(r.id)?.net ?? null as number | null })),
    [windowBase, nets],
  );

  const withheld = !isLoading && total > 0 && total < MIN_ROUNDS;
  const withheldFired = useRef(false);
  useEffect(() => {
    if (!withheld || withheldFired.current) return;
    withheldFired.current = true;
    analyticsEvents.track('handicap_section_withheld', {
      section: 'rounds_that_count',
      sample: total,
      required: MIN_ROUNDS,
    });
  }, [withheld, total]);

  if (isLoading || total === 0) return null;

  // ── Withheld: fewer than a full window ────────────────────────────────
  if (withheld) {
    return (
      <HcpSection
        hairline
        kicker={t('common:handicap.roundsThatCount.eyebrow')}
        heading={t('common:handicap.roundsThatCount.heading')}
        meta={t('common:handicap.roundsThatCount.metaAll', { count: total })}
      >
        <p style={{ margin: 0, fontSize: 13, color: CHART.MUTE, lineHeight: 1.55 }}>
          {t('common:handicap.roundsThatCount.withheldBody', { count: total })}
        </p>
      </HcpSection>
    );
  }

  /* THE CUT (§4.4): the highest differential among rounds where is_counter
     is true — the eighth-best. Every counter sits on or under it, every
     non-counter above, so the line and the bar colours cannot disagree.
     Null when the counter set is empty — nothing to rule. */
  const counters = window20.filter((r) => r.is_counter && r.diff != null);
  const cutLine = counters.length ? Math.max(...counters.map((r) => r.diff as number)) : null;
  const countingEight = [...counters].sort((a, b) => (a.diff as number) - (b.diff as number));

  const selIdxRaw = selId != null ? window20.findIndex((r) => r.id === selId) : -1;
  /* AA4: no explicit choice yet → the newest round (rightmost bar). */
  const selIdx = selIdxRaw >= 0 ? selIdxRaw : window20.length ? window20.length - 1 : null;
  const activeId = selIdx != null ? window20[selIdx].id : null;
  const selected = selIdx != null ? window20[selIdx] : null;
  const roundLabel = (r: (typeof window20)[number]) =>
    t(r.is_counter ? 'common:handicap.mechanism.roundLabelCounts' : 'common:handicap.mechanism.roundLabelNotCounting', {
      date: formatDayMonthShortGB(r.play_date),
      course: r.course_name ?? '',
      diff: r.diff != null ? fmtDiff(r.diff) : '',
    });

  const onSelect = (i: number) => {
    const r = window20[i];
    if (!r) return;
    setSelId(r.id);
    analyticsEvents.track('handicap_counting_point_tapped', {
      score_id: r.id,
      counts: r.is_counter,
      position: i + 1,
      of: window20.length,
    });
  };

  return (
    <>
      <HcpSection
        hairline
        kicker={t('common:handicap.mechanism.kicker')}
        heading={t('common:handicap.mechanism.title')}
      >
        {/* §4.1 caption. */}
        <p style={{ margin: '0 0 14px', fontSize: 12.5, fontWeight: 400, lineHeight: 1.45, color: CHART.MUTE }}>
          {t('common:handicap.mechanism.caption')}
        </p>

        {/* AA2 detail block — two lines, always rendered (newest by default). */}
        <div data-testid="mechanism-detail" style={{ height: SLOT_H, marginBottom: 6 }}>
          {selected && (
            <>
              <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 12 }}>
                <span
                  data-testid="detail-course"
                  style={{
                    fontSize: 12.5, fontWeight: 700, color: CHART.INK, minWidth: 0,
                    overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                  }}
                >
                  {selected.course_name ?? ''}
                </span>
                <span
                  data-testid="detail-counts"
                  style={{ fontSize: 12.5, fontWeight: 700, flexShrink: 0, color: selected.is_counter ? A.IMPROVED : CHART.MUTE }}
                >
                  {selected.is_counter
                    ? t('common:handicap.roundsThatCount.counts')
                    : t('common:handicap.roundsThatCount.doesNotCount')}
                </span>
              </div>
              <div style={{ display: 'flex', alignItems: 'baseline', gap: 12, marginTop: 4, whiteSpace: 'nowrap' }}>
                {([
                  ['gross', selected.gross != null
                    ? `${selected.gross}${selected.par != null ? ` (${fmtToPar(selected.gross - selected.par)})` : ''}`
                    : ''],
                  ['net', selected.net != null ? String(selected.net) : ''],
                  ['diff', selected.diff != null ? fmtDiff(selected.diff) : ''],
                ] as const).map(([k, v]) => (
                  <span key={k} style={{ display: 'inline-flex', alignItems: 'baseline', gap: 4 }}>
                    <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: CHART.DIM }}>
                      {t(`common:handicap.mechanism.detail.${k}`)}
                    </span>
                    <span data-testid={`detail-${k}`} style={{ fontSize: 12.5, fontWeight: 700, color: CHART.INK, ...FIG }}>{v}</span>
                  </span>
                ))}
                <span data-testid="detail-date" style={{ fontSize: 11, fontWeight: 600, color: CHART.DIM, marginLeft: 'auto', ...FIG }}>
                  {formatDayMonthShortGB(selected.play_date)}
                </span>
              </div>
            </>
          )}
        </div>

        <LastTwentyBars
          rounds={window20.map((r) => ({ diff: r.diff, counts: r.is_counter }))}
          cut={cutLine != null ? { value: cutLine } : null}
          oldestLabel={t('common:handicap.mechanism.oldest', { date: formatDayMonthShortGB(window20[0].play_date) })}
          newestLabel={t('common:handicap.mechanism.newest', { date: formatDayMonthShortGB(window20[window20.length - 1].play_date) })}
          selectedIndex={selIdx}
          onSelectIndex={onSelect}
          labels={window20.map(roundLabel)}
        />

        {/* §4.6 THE COUNTING EIGHT — two-column tiles, best first, full course names. */}
        {countingEight.length > 0 && (
          <>
            <div
              style={{
                marginTop: 22, fontSize: 9.5, fontWeight: 700, letterSpacing: '0.14em',
                textTransform: 'uppercase', color: A.IMPROVED,
              }}
            >
              {t('common:handicap.mechanism.countingEight')}
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: 8, marginTop: 10 }}>
              {countingEight.map((r) => (
                <button
                  key={r.id}
                  type="button"
                  data-round-id={r.id}
                  aria-label={roundLabel(r)}
                  aria-pressed={activeId === r.id}
                  onClick={() => onSelect(window20.findIndex((w) => w.id === r.id))}
                  style={{
                    display: 'flex', flexDirection: 'column', gap: 10,
                    padding: '11px 12px 10px', borderRadius: 12, background: MEMBER_PANEL,
                    border: 0, margin: 0, textAlign: 'left', minWidth: 0,
                    font: 'inherit', cursor: 'pointer', WebkitTapHighlightColor: 'transparent',
                    /* Dim the other seven only when the selected round is one of the eight. */
                    opacity: activeId != null && activeId !== r.id && countingEight.some((c) => c.id === activeId) ? 0.55 : 1,
                  }}
                >
                  <span
                    style={{
                      fontSize: 12.5, fontWeight: 600, lineHeight: 1.3,
                      color: inkWithAlpha(CHART.INK, 0.86), overflowWrap: 'anywhere',
                    }}
                  >
                    {r.course_name ?? ''}
                  </span>
                  <span style={{ marginTop: 'auto', display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 8 }}>
                    <span style={{ fontSize: 10.5, fontWeight: 600, color: CHART.DIM, whiteSpace: 'nowrap' }}>
                      {formatDayMonthShortGB(r.play_date)}
                    </span>
                    <span
                      style={{
                        fontSize: 22, fontWeight: 800, letterSpacing: '-0.01em', lineHeight: 1,
                        fontVariantNumeric: 'tabular-nums lining-nums', color: A.IMPROVED,
                      }}
                    >
                      {fmtDiff(r.diff as number)}
                    </span>
                  </span>
                </button>
              ))}
            </div>
          </>
        )}
      </HcpSection>

    </>
  );
};

export default RoundsThatCountSection;

/**
 * CompareSheet - "How you compare".
 *
 * ONE sheet replaces the rivalry mechanic. Two states:
 *
 *   LIST   - a search field, then the six players the member played with most
 *            recently. Search widens to ANYONE the member can find, which is
 *            the point: the old mechanic only worked against a fixed set of
 *            slots.
 *   DETAIL - the heads row, then paired stat rows.
 *
 * DETAIL has TWO MODES and the mode is decided by ONE fact - whether the two
 * have ever played the same course on the same day:
 *
 *   SHARED (>=1 shared round) - head-to-head figures, footnoted with the
 *            sample. This is what the rivalry page carried.
 *   SEASON  (0 shared rounds) - season figures side by side, footnoted to say
 *            so. NOT an empty state: comparing two members who have never met
 *            is the common case once search is open to everyone.
 *
 * HH3: DETAIL is now "Head to head" (HeadToHeadDetail.tsx): heads, You v,
 * Together, Course by course. No amber; leader rules in headToHeadRules.ts.
 * The SHARED/SEASON split above survives only as Together vs its one-line
 * never-played replacement.
 */
import React from 'react';
import { useTranslation } from 'react-i18next';
import { X, ArrowLeft, Search } from 'lucide-react';
import { BottomSheet } from '@/components/ui/BottomSheet';
import { useDebouncedValue } from '@/hooks/useDebouncedValue';
import { useSharedRounds, useSharedRoundCounts, useWhsConnection } from '@/lib/whs/hooks';
import { useEntityPickerSearch } from '@/features/search-v2/hooks/useEntityPickerSearch';
import { useCompareIdentities } from './useCompareIdentities';
import { useCompareRecent } from './useCompareRecent';
import { analyticsEvents } from '@/utils/analyticsEvents';
import { CHART, CHART_FONT, LABEL_STYLE } from '../../charts';
import ComparePersonRow, { type ComparePerson } from './ComparePersonRow';
import { useCompareStats } from './useCompareStats';
import HeadToHeadDetail from './HeadToHeadDetail';

import type { CompareSource } from './events';
import { FIELD_PAINT_CLASS, FIELD_PLACEHOLDER_CLASS } from '@/lib/tokens/field';

const RECENT_LIMIT = 6;

interface Props {
  open: boolean;
  onClose: () => void;
  /** The viewing member. All figures on the left-hand side are theirs. */
  viewerUserId: string;
  /** Pre-selected player, from a deep link or the friend-view control. */
  initialTargetUserId?: string | null;
  from: CompareSource;
}

export const CompareSheet: React.FC<Props> = ({
  open,
  onClose,
  viewerUserId,
  initialTargetUserId = null,
  from,
}) => {
  const { t } = useTranslation('common');
  const [target, setTarget] = React.useState<ComparePerson | null>(null);
  const [query, setQuery] = React.useState('');
  const debouncedQuery = useDebouncedValue(query, 250);

  const { data: connection } = useWhsConnection(viewerUserId);
  /**
   * IDENTITY + ORDER. The recent list is built by useCompareRecent, THE ONE
   * definition shared with the Circle entry panel so the two surfaces cannot
   * disagree about who "recent" is. Names and photos come from user_profiles,
   * never from the leaderboard's England Golf friend_name.
   */
  const recent = useCompareRecent(viewerUserId, RECENT_LIMIT, open);


  const searching = debouncedQuery.trim().length > 0;
  const { people } = useEntityPickerSearch({
    query: debouncedQuery,
    enabled: open && searching && !target,
    limit: 12,
  });

  const searchResults = React.useMemo<ComparePerson[]>(
    () =>
      (people ?? [])
        .filter((p) => p.id !== viewerUserId)
        .map((p) => ({
          userId: p.id,
          name: p.display_name,
          avatarUrl: p.avatar_url,
          index: null,
          contextLine: null,
        })),
    [people, viewerUserId],
  );

  /**
   * ONE batched RPC for whichever list is on screen - six recent rows or the
   * search results - instead of a query per row. Cached per id-set, so
   * toggling back to the recent list or re-typing a query costs nothing.
   */
  const visibleIds = React.useMemo(
    () => (searching ? searchResults : recent).map((p) => p.userId),
    [searching, searchResults, recent],
  );
  const { data: sharedCounts } = useSharedRoundCounts(
    viewerUserId,
    visibleIds,
    open && !target,
  );

  /**
   * Deep link / friend-view pre-selection, through THE SAME resolver.
   *
   * `recent` is only six rows, so most deep links miss it; the id is then read
   * from user_profiles directly. WHILE IT IS IN FLIGHT THE TARGET CARRIES NO
   * NAME - not the sheet's title, not "Player", nothing. A fabricated identity
   * over a stranger's genuine record is a mis-attribution, and the old code
   * named people after this sheet's own heading.
   *
   * ON A FAILED OR EMPTY LOOKUP the sheet falls back to its ENTRY STATE so the
   * member picks someone real.
   */
  const { data: deepIdentities, isFetched: deepFetched } = useCompareIdentities(
    initialTargetUserId ? [initialTargetUserId] : [],
    open && !!initialTargetUserId,
  );

  React.useEffect(() => {
    if (!open || !initialTargetUserId) return;
    const hit = recent.find((p) => p.userId === initialTargetUserId);
    if (hit?.name) {
      setTarget(hit);
      return;
    }
    const resolved = deepIdentities?.[initialTargetUserId];
    if (resolved) {
      setTarget({
        userId: resolved.userId,
        name: resolved.name,
        avatarUrl: resolved.avatarUrl,
        index: hit?.index ?? null,
        contextLine: hit?.contextLine ?? null,
      });
      return;
    }
    if (deepFetched) {
      setTarget(null); // Unidentifiable - show the entry state, not a comparison.
      return;
    }
    setTarget({
      userId: initialTargetUserId,
      name: null,
      avatarUrl: null,
      index: null,
      contextLine: null,
    });
  }, [open, initialTargetUserId, recent, deepIdentities, deepFetched]);

  React.useEffect(() => {
    if (!open) return;
    analyticsEvents.track('handicap_compare_opened', {
      from,
      pre_selected: !!initialTargetUserId,
    });
  }, [open, from, initialTargetUserId]);

  React.useEffect(() => {
    if (!searching) return;
    analyticsEvents.track('handicap_compare_searched', {
      query_length: debouncedQuery.trim().length,
      results: searchResults.length,
    });
  }, [searching, debouncedQuery, searchResults.length]);

  const { data: shared } = useSharedRounds(viewerUserId, target?.userId ?? null);
  const { data: season } = useCompareStats(
    viewerUserId,
    connection?.id,
    target?.userId,
    target?.name ?? undefined,
  );

  /** HH3: the heads row shows REAL photos for both sides, one batched read. */
  const { data: heads } = useCompareIdentities(
    target ? [viewerUserId, target.userId] : [],
    open && !!target,
  );
  const targetFirst = (target?.name ?? '').trim().split(/\s+/)[0] ?? '';

  const handleSelect = (person: ComparePerson, sharedRounds: number) => {
    analyticsEvents.track('handicap_compare_player_picked', {
      target_user_id: person.userId,
      shared_rounds: sharedRounds,
      mode: sharedRounds > 0 ? 'shared' : 'season',
      from_search: searching,
    });
    setTarget(person);
  };

  const backToList = () => {
    setTarget(null);
    setQuery('');
  };

  const handleClose = () => {
    setTarget(null);
    setQuery('');
    onClose();
  };

  return (
    <BottomSheet
      open={open}
      onClose={handleClose}
      ariaLabelledBy="handicap-compare-title"
      maxHeight="85dvh"
      style={{
        height: 'auto',
        maxHeight: '85dvh',
        display: 'flex',
        flexDirection: 'column',
        fontFamily: CHART_FONT,
      }}
    >
      {/* HH3: the DETAIL state carries the Head to head header; LIST is unchanged. */}
      {target ? (
        <div data-hh-header style={{ flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, padding: '12px 18px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, minWidth: 0 }}>
            {!initialTargetUserId && (
              <button type="button" onClick={backToList} aria-label={t('handicap.compare.back')} style={{ border: 'none', background: 'transparent', color: 'rgba(248,250,252,0.55)', cursor: 'pointer', padding: 4, marginLeft: -4, lineHeight: 0, flexShrink: 0 }}>
                <ArrowLeft size={18} strokeWidth={2.2} />
              </button>
            )}
            <div style={{ minWidth: 0 }}>
              <div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.18em', color: 'rgba(248,250,252,0.5)' }}>HEAD TO HEAD</div>
              <div id="handicap-compare-title" style={{ marginTop: 3, fontSize: 20, fontWeight: 700, letterSpacing: '-0.02em', color: '#F8FAFC' }}>
                {target.name ? `You and ${targetFirst}` : <span aria-hidden style={{ display: 'inline-block', width: 148, height: 16, borderRadius: 4, background: 'rgba(255,255,255,0.06)', verticalAlign: 'middle' }} />}
              </div>
            </div>
          </div>
          <button type="button" onClick={handleClose} aria-label={t('handicap.compare.close')} style={{ width: 34, height: 34, borderRadius: 12, border: '1px solid rgba(255,255,255,0.14)', background: 'transparent', color: 'rgba(248,250,252,0.8)', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', flexShrink: 0, padding: 0 }}>
            <X size={15} strokeWidth={2} />
          </button>
        </div>
      ) : (
      <div
        style={{
          flexShrink: 0,
          padding: '6px 16px 12px',
          borderBottom: `1px solid ${CHART.BORDER}`,
          display: 'flex',
          alignItems: 'flex-start',
          justifyContent: 'space-between',
          gap: 12,
        }}
      >
        <div style={{ display: 'flex', alignItems: 'flex-start', gap: 10, minWidth: 0 }}>
          {target && (
            <button
              type="button"
              onClick={backToList}
              aria-label={t('handicap.compare.back')}
              style={{
                border: 'none',
                background: 'transparent',
                color: CHART.MUTE,
                cursor: 'pointer',
                padding: 4,
                marginLeft: -4,
                lineHeight: 0,
                flexShrink: 0,
              }}
            >
              <ArrowLeft size={18} strokeWidth={2.2} />
            </button>
          )}
          <div style={{ minWidth: 0 }}>
            <div style={{ ...LABEL_STYLE, color: CHART.MUTE }}>
              {t('handicap.compare.kicker')}
            </div>
            <div
              id="handicap-compare-title"
              style={{
                marginTop: 3,
                fontSize: 17,
                fontWeight: 700,
                color: CHART.INK,
                letterSpacing: '-0.01em',
              }}
            >
              {!target ? (
                t('handicap.compare.title')
              ) : target.name ? (
                t('handicap.compare.youAnd', { name: target.name })
              ) : (
                // Identity in flight: a shell, never a placeholder name.
                <span
                  aria-hidden
                  style={{
                    display: 'inline-block',
                    width: 148,
                    height: 14,
                    borderRadius: 4,
                    background: CHART.PANEL_2,
                    verticalAlign: 'middle',
                  }}
                />
              )}
            </div>
          </div>
        </div>
        <button
          type="button"
          onClick={handleClose}
          aria-label={t('handicap.compare.close')}
          style={{
            border: 'none',
            background: 'transparent',
            color: CHART.MUTE,
            cursor: 'pointer',
            padding: 6,
            margin: -6,
            lineHeight: 0,
            flexShrink: 0,
          }}
        >
          <X size={20} strokeWidth={2} />
        </button>
      </div>
      )}

      {/* Scroller */}
      {/* `no-scrollbar` is the app's existing utility (src/index.css) used by the
          other analytical sheets; it hides the bar without touching keyboard or
          assistive scrolling. */}
      <div
        className="no-scrollbar"
        style={{ flex: 1, minHeight: 0, overflowY: 'auto', WebkitOverflowScrolling: 'touch' }}
      >
        {!target && (
          <>
            {/* Search */}
            <div style={{ padding: '14px 16px 12px' }}>
              {/* FIELD CANON — ground is CHART.CANVAS, so the canvas set. */}
              <div
                className={FIELD_PAINT_CLASS}
                style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '9px 12px' }}
              >
                <Search size={15} strokeWidth={2.2} color={CHART.DIM} />
                <input
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  placeholder={t('handicap.compare.searchPlaceholder')}
                  aria-label={t('handicap.compare.searchPlaceholder')}
                  style={{
                    flex: 1,
                    minWidth: 0,
                    background: 'transparent',
                    border: 'none',
                    outline: 'none',
                    color: CHART.INK,
                    fontFamily: CHART_FONT,
                    fontSize: 14,
                    fontWeight: 600,
                  }}
                />
              </div>
              <div style={{ ...LABEL_STYLE, marginTop: 10, color: CHART.MUTE }}>
                {searching
                  ? t('handicap.compare.results')
                  : t('handicap.compare.recent')}
              </div>
            </div>

            {(searching ? searchResults : recent).map((p) => (
              <ComparePersonRow
                key={p.userId}
                person={p}
                sharedCount={sharedCounts?.[p.userId] ?? 0}
                onSelect={handleSelect}
              />
            ))}

            {searching && searchResults.length === 0 && (
              <div
                style={{
                  padding: '18px 16px',
                  borderTop: `1px solid ${CHART.BORDER}`,
                  fontSize: 13,
                  color: CHART.MUTE,
                }}
              >
                {t('handicap.compare.noMatch')}
              </div>
            )}

            {!searching && recent.length === 0 && (
              <div
                style={{
                  padding: '18px 16px',
                  borderTop: `1px solid ${CHART.BORDER}`,
                  fontSize: 13,
                  color: CHART.MUTE,
                }}
              >
                {t('handicap.compare.prompt')}
              </div>
            )}
          </>
        )}

        {target && (
          <HeadToHeadDetail
            me={{ userId: viewerUserId, name: heads?.[viewerUserId]?.name ?? null, avatarUrl: heads?.[viewerUserId]?.avatarUrl ?? null }}
            them={{ userId: target.userId, name: target.name, avatarUrl: heads?.[target.userId]?.avatarUrl ?? target.avatarUrl }}
            firstName={targetFirst}
            season={season}
            shared={shared}
          />
        )}
      </div>
    </BottomSheet>
  );
};

export default CompareSheet;

/**
 * HeadToHeadDetail - HH3 DETAIL state of CompareSheet ("Head to head").
 *
 * Order is fixed by the signed-off mock: heads row, then YOU V {FIRST} (every
 * round each has posted, from useCompareStats), then TOGETHER (scoreboards from
 * useSharedRounds) with COURSE BY COURSE accordions inside it. With no shared
 * rounds, Together is replaced by one line and You v still shows.
 *
 * NO AMBER: leader full white, the other dimmed (rules in headToHeadRules.ts).
 * The header (kicker, title, close) is owned by CompareSheet.
 */
import React from 'react';
import { getInitialsFromName, getAvatarFallbackGradient } from '@/lib/avatarFallback';
import { shortCourseName } from '@/lib/courses/shortCourseName';
import type { SharedRoundsResult } from '@/lib/whs/api';
import type { HeadToHeadStats } from './h2hStats';
import {
  HH_INK, HH_DIM, HH_BAR_OTHER, leaderOf, shareOf, figurePaint, fmtGap,
  groupByCourse, recordLeadLine, shortDate, resolveGroupCourseId, type Polarity, type Record3, type CourseGroup,
} from './headToHeadRules';

const KICK: React.CSSProperties = { fontSize: 10.5, fontWeight: 800, letterSpacing: '0.18em', color: 'rgba(248,250,252,0.5)', textTransform: 'uppercase' };
const COLH: React.CSSProperties = { fontSize: 9.5, fontWeight: 800, letterSpacing: '0.14em', color: 'rgba(248,250,252,0.45)', textTransform: 'uppercase' };
const TAB: React.CSSProperties = { fontVariantNumeric: 'tabular-nums' };
const HAIR = '1px solid rgba(255,255,255,0.07)';
const DASH = '\u2013';
const ROUNDS_SHOWN = 5;

export interface HeadPerson { userId: string; name: string | null; avatarUrl: string | null }

interface Props {
  me: HeadPerson;
  them: HeadPerson;
  firstName: string;
  season: HeadToHeadStats | null | undefined;
  shared: SharedRoundsResult | null | undefined;
}

const Head: React.FC<{ p: HeadPerson; label: string; index: number | null | undefined; side: 'me' | 'them' }> = ({ p, label, index, side }) => (
  <div data-hh-head={side} style={{ textAlign: 'center', minWidth: 0 }}>
    <div style={{ width: 58, height: 60, borderRadius: '34%', margin: '0 auto', border: '2px solid rgba(255,255,255,0.18)', overflow: 'hidden', background: p.avatarUrl ? 'rgba(255,255,255,0.06)' : getAvatarFallbackGradient(p.userId), display: 'flex', alignItems: 'center', justifyContent: 'center', color: HH_INK, fontSize: 17, fontWeight: 700 }}>
      {p.avatarUrl ? <img src={p.avatarUrl} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : p.name ? <span>{getInitialsFromName(p.name)}</span> : null}
    </div>
    <div style={{ fontSize: 14, fontWeight: 700, marginTop: 7, color: HH_INK }}>{label}</div>
    <div style={{ fontSize: 12, color: 'rgba(248,250,252,0.55)', marginTop: 1 }}>
      Index <em style={{ fontStyle: 'normal', color: HH_INK, fontWeight: 700 }}>{index == null ? DASH : index < 0 ? `+${Math.abs(index).toFixed(1)}` : index.toFixed(1)}</em>
    </div>
  </div>
);

interface VsDef { key: string; label: string; pol: Polarity; me: number | null | undefined; them: number | null | undefined; decimals?: number }

const fmt = (v: number | null | undefined, d = 0) => (v == null || !Number.isFinite(v) ? DASH : d ? v.toFixed(d) : String(v));

const VsRow: React.FC<{ d: VsDef; first: boolean }> = ({ d, first }) => {
  const leader = leaderOf(d.pol, d.me, d.them);
  const share = leader === 'none' ? 0 : shareOf(d.pol, d.me as number, d.them as number);
  const segMe = leader === 'me' || leader === 'tie' ? HH_INK : HH_BAR_OTHER;
  const segThem = leader === 'them' || leader === 'tie' ? HH_INK : HH_BAR_OTHER;
  return (
    <div data-hh-vs={d.key} data-leader={leader} style={{ display: 'grid', gridTemplateColumns: '52px minmax(0,1fr) 52px', alignItems: 'center', gap: 8, padding: '11px 0', borderTop: first ? 0 : HAIR, ...TAB }}>
      <div data-hh-fig="me" style={{ fontSize: 17, ...figurePaint('me', leader) }}>{fmt(d.me, d.decimals)}</div>
      <div style={{ textAlign: 'center', minWidth: 0 }}>
        <div style={{ ...COLH, color: 'rgba(248,250,252,0.5)' }}>{d.label}</div>
        {leader !== 'none' && (
          <div data-hh-bar style={{ display: 'flex', height: 4, marginTop: 7, gap: 2 }}>
            <i style={{ flex: share, height: '100%', borderRadius: 2, background: segMe }} />
            <i style={{ flex: 1 - share, height: '100%', borderRadius: 2, background: segThem }} />
          </div>
        )}
      </div>
      <div data-hh-fig="them" style={{ fontSize: 17, textAlign: 'right', ...figurePaint('them', leader) }}>{fmt(d.them, d.decimals)}</div>
    </div>
  );
};

const Pair: React.FC<{ a: number; b: number }> = ({ a, b }) => (
  <>
    <span style={{ color: a >= b ? HH_INK : HH_DIM }}>{a}</span>
    <span style={{ color: 'rgba(248,250,252,0.35)' }}>{DASH}</span>
    <span style={{ color: b >= a ? HH_INK : HH_DIM }}>{b}</span>
  </>
);

const Board: React.FC<{ kind: 'gross' | 'stableford'; label: string; r: Record3; first: string }> = ({ kind, label, r, first }) => {
  const meLead = r.wins > r.losses;
  const themLead = r.losses > r.wins;
  const meBright = !themLead;
  const themBright = !meLead;
  return (
    <div data-hh-board={kind} style={{ border: '1px solid rgba(255,255,255,0.1)', borderRadius: 16, padding: 12, background: 'rgba(255,255,255,0.025)', minWidth: 0 }}>
      <div style={{ ...KICK, textAlign: 'center' }}>{label}</div>
      <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'center', gap: 6, marginTop: 8, ...TAB }}>
        <b data-hh-score="me" style={{ fontSize: 34, fontWeight: 800, letterSpacing: '-0.04em', lineHeight: 1, color: meBright ? HH_INK : HH_DIM }}>{r.wins}</b>
        <i style={{ fontStyle: 'normal', color: 'rgba(248,250,252,0.35)', fontSize: 20 }}>{DASH}</i>
        <b data-hh-score="them" style={{ fontSize: 34, fontWeight: 800, letterSpacing: '-0.04em', lineHeight: 1, color: themBright ? HH_INK : HH_DIM }}>{r.losses}</b>
      </div>
      <div style={{ display: 'flex', height: 5, borderRadius: 3, overflow: 'hidden', marginTop: 10, gap: 2 }}>
        <i style={{ flex: r.wins, background: meLead ? HH_INK : 'rgba(255,255,255,0.32)' }} />
        <i style={{ flex: r.ties, background: 'rgba(255,255,255,0.14)' }} />
        <i style={{ flex: r.losses, background: themLead ? HH_INK : 'rgba(255,255,255,0.32)' }} />
      </div>
      <div data-hh-lead style={{ fontSize: 12, fontWeight: 700, textAlign: 'center', marginTop: 8, color: HH_INK }}>{recordLeadLine(r, first)}</div>
      <div style={{ fontSize: 11, color: HH_DIM, textAlign: 'center', marginTop: 2 }}>{r.ties} halved</div>
    </div>
  );
};

const CourseCard: React.FC<{ g: CourseGroup; first: string; defaultOpen: boolean; meBest?: { gross: number | null; points: number | null }; themBest?: { gross: number | null; points: number | null } }> = ({ g, first, defaultOpen, meBest, themBest }) => {
  const [open, setOpen] = React.useState(defaultOpen);
  const [all, setAll] = React.useState(false);
  const n = g.rounds.length;
  const shown = all ? g.rounds : g.rounds.slice(0, ROUNDS_SHOWN);
  const best = (b?: { gross: number | null; points: number | null }) => `${b?.gross ?? DASH} \u00B7 ${b?.points ?? DASH} pts`;
  const recSmall: React.CSSProperties = { color: 'rgba(248,250,252,0.45)', fontWeight: 800, fontSize: 8.5, letterSpacing: '0.12em', marginRight: 5 };
  return (
    <div data-hh-course={g.courseId} data-open={open ? 'true' : 'false'} style={{ border: '1px solid rgba(255,255,255,0.1)', borderRadius: 16, marginTop: 10, overflow: 'hidden', background: 'rgba(255,255,255,0.02)' }}>
      <button type="button" aria-expanded={open} onClick={() => setOpen((v) => !v)} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '12px 14px', width: '100%', border: 0, background: 'transparent', textAlign: 'left', cursor: 'pointer', color: HH_INK, fontFamily: 'inherit' }}>
        <div style={{ flex: 1, minWidth: 0 }}>
          <b style={{ display: 'block', fontSize: 14.5, fontWeight: 700, lineHeight: 1.25, overflowWrap: 'anywhere' }}>{shortCourseName(g.courseName)}</b>
          <span style={{ display: 'block', fontSize: 11.5, color: 'rgba(248,250,252,0.5)', marginTop: 2 }}>{n} {n === 1 ? 'round' : 'rounds'} together</span>
        </div>
        <div style={{ textAlign: 'right', fontSize: 12.5, fontWeight: 700, lineHeight: 1.55, whiteSpace: 'nowrap', ...TAB }}>
          <div><small style={recSmall}>GROSS</small><Pair a={g.gross.wins} b={g.gross.losses} /></div>
          <div><small style={recSmall}>PTS</small><Pair a={g.points.wins} b={g.points.losses} /></div>
        </div>
        <div aria-hidden style={{ width: 22, height: 22, flex: '0 0 auto', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'rgba(248,250,252,0.55)', transition: 'transform 250ms', transform: open ? 'rotate(180deg)' : 'none', fontSize: 13 }}>{'\u25BE'}</div>
      </button>
      <div data-hh-course-body style={{ maxHeight: open ? (all ? 4000 : 600) : 0, overflow: 'hidden', transition: 'max-height 300ms cubic-bezier(.2,.8,.2,1)' }}>
        {open && (
          <div style={{ padding: '0 14px 12px', borderTop: HAIR }}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginTop: 12 }}>
              {[{ b: meBest, l: 'YOUR BEST EVER' }, { b: themBest, l: `${first.toUpperCase()}'S BEST EVER` }].map((x) => (
                <div key={x.l} style={{ borderRadius: 12, background: 'rgba(255,255,255,0.04)', padding: '9px 10px' }}>
                  <b style={{ display: 'block', fontSize: 17, fontWeight: 700, color: HH_INK, ...TAB }}>{best(x.b)}</b>
                  <span style={{ display: 'block', fontSize: 9.5, fontWeight: 800, letterSpacing: '0.12em', color: 'rgba(248,250,252,0.5)', marginTop: 2 }}>{x.l}</span>
                </div>
              ))}
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '52px minmax(0,1fr) 52px 52px', gap: 8, marginTop: 12 }}>
              <span /><span /><span style={{ ...COLH, textAlign: 'right' }}>YOU</span><span style={{ ...COLH, textAlign: 'right' }}>{first}</span>
            </div>
            {shown.map((r, i) => {
              const lead = leaderOf('low', r.user_gross, r.rival_gross);
              const verdict = r.user_gross < r.rival_gross ? 'You won on gross' : r.user_gross > r.rival_gross ? `${first} won on gross` : 'Halved on gross';
              return (
                <div key={`${r.play_date}-${i}`} data-hh-round style={{ display: 'grid', gridTemplateColumns: '52px minmax(0,1fr) 52px 52px', gap: 8, alignItems: 'center', padding: '10px 0', borderTop: i === 0 ? 0 : HAIR, ...TAB }}>
                  <div style={{ fontSize: 11.5, color: 'rgba(248,250,252,0.55)', lineHeight: 1.25 }}>{shortDate(r.play_date)}</div>
                  <div style={{ fontSize: 12.5, color: 'rgba(248,250,252,0.6)', lineHeight: 1.25 }}>{verdict}</div>
                  {(['me', 'them'] as const).map((side) => (
                    <div key={side} data-hh-gross={side} style={{ textAlign: 'right', fontSize: 14, fontWeight: 700, color: lead === 'tie' || lead === side ? HH_INK : HH_DIM }}>
                      {side === 'me' ? r.user_gross : r.rival_gross}
                      <small style={{ display: 'block', fontSize: 10.5, fontWeight: 600, color: 'rgba(248,250,252,0.5)', marginTop: 1 }}>{side === 'me' ? r.user_stableford : r.rival_stableford} pts</small>
                    </div>
                  ))}
                </div>
              );
            })}
            {!all && n > ROUNDS_SHOWN && (
              <button type="button" data-hh-all onClick={() => setAll(true)} style={{ display: 'block', width: '100%', border: 0, background: 'transparent', fontSize: 12.5, fontWeight: 700, color: 'rgba(248,250,252,0.7)', textAlign: 'center', paddingTop: 10, cursor: 'pointer', fontFamily: 'inherit' }}>
                All {n} rounds here {'\u203A'}
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export const HeadToHeadDetail: React.FC<Props> = ({ me, them, firstName, season, shared }) => {
  const first = firstName || '';
  const mi = season?.me.handicap_index ?? null;
  const ti = season?.them.handicap_index ?? null;
  const rows: VsDef[] = [
    { key: 'birdies', label: 'Birdies', pol: 'high', me: season?.me.birdies, them: season?.them.birdies },
    { key: 'eagles', label: 'Eagles', pol: 'high', me: season?.me.eagles, them: season?.them.eagles },
    { key: 'sub80', label: 'Rounds under 80', pol: 'high', me: season?.me.sub80_rounds, them: season?.them.sub80_rounds },
    { key: 'bestGross', label: 'Best gross', pol: 'low', me: season?.me.lowest_gross, them: season?.them.lowest_gross },
    { key: 'bestStableford', label: 'Best Stableford', pol: 'high', me: season?.me.best_stableford, them: season?.them.best_stableford },
    { key: 'avgGross', label: 'Average gross', pol: 'low', me: season?.me.avg_gross, them: season?.them.avg_gross, decimals: 1 },
    { key: 'avgPoints', label: 'Average points', pol: 'high', me: season?.me.avg_points, them: season?.them.avg_points, decimals: 1 },
    { key: 'top100', label: 'Top 100 courses played', pol: 'high', me: season?.me.top100_played, them: season?.them.top100_played },
  ];
  const count = shared?.shared_rounds_count ?? 0;
  const groups = React.useMemo(() => groupByCourse(shared?.shared_round_results ?? []), [shared]);

  return (
    <div data-hh-detail style={{ padding: '0 18px 32px', color: HH_INK }}>
      <div data-hh-heads style={{ display: 'grid', gridTemplateColumns: '1fr auto 1fr', alignItems: 'center', gap: 8, marginTop: 4 }}>
        <Head p={me} label="You" index={mi} side="me" />
        <div style={{ textAlign: 'center' }}>
          <b data-hh-gap style={{ display: 'block', fontSize: 22, fontWeight: 700, letterSpacing: '-0.02em', ...TAB }}>{mi != null && ti != null ? fmtGap(mi - ti) : DASH}</b>
          <span style={{ fontSize: 9.5, fontWeight: 800, letterSpacing: '0.14em', color: 'rgba(248,250,252,0.5)' }}>SHOTS APART</span>
        </div>
        <Head p={them} label={first} index={ti} side="them" />
      </div>

      <section data-hh-section="vs" style={{ marginTop: 24 }}>
        <div style={KICK}>YOU V {first.toUpperCase()}</div>
        <div style={{ fontSize: 12, color: 'rgba(248,250,252,0.5)', marginTop: 4 }}>Every round you've each posted, at any course.</div>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 10 }}>
          <span style={COLH}>YOU</span><span style={COLH}>{first}</span>
        </div>
        <div>{rows.map((d, i) => <VsRow key={d.key} d={d} first={i === 0} />)}</div>
      </section>

      {count === 0 ? (
        <div data-hh-never style={{ marginTop: 24, fontSize: 13, color: 'rgba(248,250,252,0.6)', lineHeight: 1.45 }}>
          You and {first} haven't played the same course on the same day yet.
        </div>
      ) : (
        <section data-hh-section="together" style={{ marginTop: 24 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
            <div style={KICK}>TOGETHER</div>
            <span style={{ fontSize: 12, fontWeight: 700, color: 'rgba(248,250,252,0.55)' }}>{count} {count === 1 ? 'round' : 'rounds'}</span>
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0,1fr) minmax(0,1fr)', gap: 10, marginTop: 10 }}>
            <Board kind="gross" label="GROSS" r={{ wins: shared?.gross_record.wins ?? 0, ties: shared?.gross_record.ties ?? 0, losses: shared?.gross_record.losses ?? 0 }} first={first} />
            <Board kind="stableford" label="STABLEFORD" r={{ wins: shared?.stableford_record.wins ?? 0, ties: shared?.stableford_record.ties ?? 0, losses: shared?.stableford_record.losses ?? 0 }} first={first} />
          </div>
          <div style={{ fontSize: 12, color: 'rgba(248,250,252,0.5)', marginTop: 10, textAlign: 'center' }}>Rounds on the same course on the same day</div>

          <div data-hh-section="courses" style={{ marginTop: 20 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
              <div style={KICK}>COURSE BY COURSE</div>
              <span style={{ fontSize: 12, fontWeight: 700, color: 'rgba(248,250,252,0.55)' }}>{groups.length} {groups.length === 1 ? 'course' : 'courses'}</span>
            </div>
            {groups.map((g, i) => {
              // H2H_BEST_1: the group is keyed by a whs_courses id; resolve
              // each side's golf_courses id from its own gam rows so the
              // best-here tiles read the right course_bests entry.
              const meId = resolveGroupCourseId(g, season?.me.gam_rows ?? [], 'me');
              const themId = resolveGroupCourseId(g, season?.them.gam_rows ?? [], 'them');
              return (
                <CourseCard key={g.courseId} g={g} first={first} defaultOpen={i === 0} meBest={meId ? season?.me.course_bests?.[meId] : undefined} themBest={themId ? season?.them.course_bests?.[themId] : undefined} />
              );
            })}
          </div>
        </section>
      )}
    </div>
  );
};

export default HeadToHeadDetail;

/** CHAMPIONS_ELSEWHERE_R: connected members only, across courses they have
 * already played (the source returns a rank, so every row is a real standing).
 * No projection onto unplayed courses. No rank, field size or leader name:
 * the source does not carry the frame that would make them complete.
 * The heading count is the rendered card count by construction.
 */
import React from 'react';
import { VERDICT_KICKER, TAB_TITLE } from '@/components/courses/course-detail/about/AboutSection';
import type { LegendCategory } from '@/lib/gam/types';
import { A } from '@/features/courses/components/holes/analytical/tokens';
import { numberWord } from '@/lib/text/numbers';
import { useTitlesInReach, type TitleInReach } from '@/hooks/gam/useTitlesInReach';
import { CHAMPIONS_BOARD_DATA, championsBoardName } from '../_shared/championsOrder';
import './championsEmpty.css';

export interface ElsewhereCard { row: TitleInReach; category: LegendCategory; proportion: number }

/** VC4: member against leader, direction-aware, clamped to 0..1. */
export function reachProportion(category: LegendCategory, user: number, leader: number): number {
  const data = CHAMPIONS_BOARD_DATA[category];
  const higherWins = data.kind === 'cumulative' || data.kind === 'not-projectable';
  const ratio = higherWins ? (leader > 0 ? user / leader : 0) : (user > 0 ? leader / user : 0);
  return Math.max(0, Math.min(1, Number.isFinite(ratio) ? ratio : 0));
}

/** VC5: ordered by bar proportion, not raw gap. Unknown categories and boards
 * already held (nothing to beat) are not cards. */
export function elsewhereCards(rows: readonly TitleInReach[]): ElsewhereCard[] {
  return rows
    .filter(row => {
      // XA4: an unrecognised category is dropped, but never silently.
      if (!(row.category in CHAMPIONS_BOARD_DATA)) { console.warn('[champions] elsewhere: unrecognised category', row.category); return false; }
      return Number(row.gap) > 0;
    })
    .map(row => {
      const category = row.category as LegendCategory;
      return { row, category, proportion: reachProportion(category, Number(row.user_value), Number(row.leader_value)) };
    })
    .sort((a, b) => b.proportion - a.proportion);
}

export function ElsewhereSection({ rows }: { rows: readonly TitleInReach[] }) {
  const cards = elsewhereCards(rows);
  if (!cards.length) return null;
  return <section className="champions-empty-section" data-section="elsewhere" style={{ color: A.INK }}>
    <div className="champions-empty-kicker" style={VERDICT_KICKER}>Elsewhere</div>
    <h2 data-card-count={cards.length} style={TAB_TITLE}>{numberWord(cards.length)} {cards.length === 1 ? 'board you are' : 'boards you are'} closest to</h2>
    <div className="champions-empty-lede" style={{ color: A.MUTE }}>Across every course you have played. Ordered by how little stands between you and the top.</div>
    {cards.map(({ row, category, proportion }) => <div key={`${row.course_id}-${row.category}`} data-elsewhere-card="" data-proportion={proportion} style={{ background: A.PANEL, borderRadius: 13, padding: 13, marginTop: 13 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 8 }}>
        <div style={{ fontSize: 14, fontWeight: 700, color: A.INK }}>{row.course_name}</div>
        <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.09em', textTransform: 'uppercase', color: A.AMBER }}>{championsBoardName(category)}</div>
      </div>
      <div style={{ fontSize: 11, color: A.DIM, fontVariantNumeric: 'tabular-nums', marginTop: 3 }}>You {row.user_value} · {row.leader_value} to beat</div>
      <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0,1fr) 54px', alignItems: 'center', gap: 8, marginTop: 9 }}>
        <div style={{ height: 8, borderRadius: 4, background: `color-mix(in srgb, ${A.INK} 5%, transparent)`, overflow: 'hidden' }}>
          <div data-bar-fill="" style={{ width: `${Math.round(proportion * 100)}%`, height: '100%', background: A.AMBER, borderRadius: 4 }} />
        </div>
        <div style={{ textAlign: 'right', fontSize: 13, fontWeight: 800, color: A.AMBER, fontVariantNumeric: 'tabular-nums' }}>{Number(Number(row.gap).toFixed(1))} off</div>
      </div>
    </div>)}
    <div className="champions-empty-said" style={{ color: A.MUTE, borderColor: A.BORDER }}>Only courses you have already played appear here, because a rank is the thing that makes a gap real. <b>Courses you have never played cannot be ranked</b> and are not guessed at.</div>
  </section>;
}

/** VB1-VB3: rendered only for connected members; absent when nothing qualifies. */
export function ChampionsElsewhere({ userId }: { userId: string }) {
  const { data } = useTitlesInReach(userId);
  return <ElsewhereSection rows={data ?? []} />;
}

/** VB1/VB2: the signed-in personal member with a synced handicap; never otherwise. */
export function showElsewhere(connected: boolean, userId: string | null | undefined, actorId: string | null | undefined): boolean {
  return connected && Boolean(userId) && userId === actorId;
}

