/* EP1: new Edit profile frame and top card (ep1-top.html 1A). Scoped to .ep-shell.
   The bizc-* variables let the shared BC4 change-or-remove sheet render here. */
.ep-shell{--ep-canvas:#0B0B0D;--ep-card:#17171B;--ep-inset:#1E1E23;--ep-hair:rgba(255,255,255,0.08);--ep-ink:#F8FAFC;--ep-mute:rgba(248,250,252,0.62);--ep-dim:rgba(248,250,252,0.42);--bizc-canvas:#0B0B0D;--bizc-card:#17171B;--bizc-hair:rgba(255,255,255,0.08);--bizc-ink:#F8FAFC;--bizc-mute:rgba(248,250,252,0.62);--bizc-dim:rgba(248,250,252,0.42);min-height:100dvh;display:flex;flex-direction:column;background:var(--ep-canvas);color:var(--ep-ink);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","SF Pro Display",system-ui,sans-serif;max-width:520px;margin:0 auto;width:100%}
.ep-head{padding:calc(env(safe-area-inset-top,0px) + 14px) 16px 0;display:flex;align-items:center;gap:12px;min-height:calc(env(safe-area-inset-top,0px) + 50px);flex-shrink:0}
.ep-back{width:36px;height:36px;border-radius:999px;border:1px solid rgba(255,255,255,0.14);background:none;color:var(--ep-ink);display:flex;align-items:center;justify-content:center;flex:none;cursor:pointer}
.ep-title{flex:1;text-align:center;margin-right:48px;font-size:17px;font-weight:700}
.ep-tabs{display:flex;gap:24px;padding:0 0 0 20px;border-bottom:1px solid var(--ep-hair)}
.ep-tab{position:relative;padding:12px 0;background:none;border:0;font-size:15px;font-weight:600;color:var(--ep-mute);cursor:pointer;font-family:inherit}
.ep-tab[aria-selected="true"]{color:var(--ep-ink)}
.ep-tab[aria-selected="true"]::after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:2px;background:var(--ep-ink)}
.ep-body{padding:12px 16px calc(24px + env(safe-area-inset-bottom,0px));flex:1;min-height:0;overflow-y:auto}
.ep-shell{height:100dvh;min-height:0}
.ep-tabs{flex-shrink:0}
.ep-saved{font-size:12px;color:var(--ep-dim);text-align:center;margin:0 0 10px;background:none;border:0;width:100%;font-family:inherit;display:block}
.ep-saved[data-state="error"]{cursor:pointer}
.ep-card{background:var(--ep-card);border:1px solid rgba(255,255,255,0.08);border-radius:20px;overflow:hidden}
.ep-cover{position:relative;display:block;width:100%;padding:0;border:0;background:var(--ep-inset);cursor:pointer;overflow:hidden}
.ep-cover img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.ep-cover-fade{position:absolute;left:0;right:0;bottom:0;height:45%;background:linear-gradient(180deg,rgba(23,23,27,0) 0%,#17171B 100%)}
.ep-edit-chip{position:absolute;top:10px;right:10px;height:30px;padding:0 12px;border-radius:999px;background:rgba(11,11,13,0.6);border:1px solid rgba(255,255,255,0.18);font-size:12.5px;font-weight:600;color:var(--ep-ink);display:flex;align-items:center;gap:6px}
.ep-identity{padding:0 16px 16px;margin-top:-40px;position:relative;min-width:0}
.ep-avatar{position:relative;display:inline-flex;padding:0;border:0;background:none;cursor:pointer}
.ep-avatar-badge{position:absolute;right:-6px;bottom:-6px;width:26px;height:26px;border-radius:50%;background:var(--ep-ink);color:var(--ep-canvas);display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;border:2px solid var(--ep-card);box-sizing:border-box}
.ep-name{font-size:22px;font-weight:700;letter-spacing:-0.02em;margin-top:10px}
.ep-line{font-size:13.5px;color:var(--ep-mute);margin-top:2px}
.ep-tags{display:flex;gap:8px;margin-top:10px;min-width:0}
.ep-tag{height:28px;padding:0 10px;border-radius:999px;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.12);font-size:12.5px;font-weight:600;display:inline-flex;align-items:center;gap:4px;flex:none;white-space:nowrap}
.ep-tag b{font-variant-numeric:tabular-nums;font-weight:700}
.ep-tag-club{flex:0 1 auto;min-width:0;display:block;line-height:26px;overflow:hidden;text-overflow:ellipsis}
.ep-back:focus-visible,.ep-tab:focus-visible,.ep-cover:focus-visible,.ep-avatar:focus-visible,.ep-saved:focus-visible{outline:2px solid #F7931E;outline-offset:2px}

/* EP2: the You group and its sheets (ep2-you.html 2A–2F). */
.ep-group{font-size:10px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--ep-dim);margin:22px 4px 8px}
.ep-rows{background:var(--ep-card);border:1px solid var(--ep-hair);border-radius:18px;padding:0 16px}
.ep-row{display:flex;align-items:center;gap:12px;width:100%;min-height:52px;padding:13px 0;border:0;border-top:1px solid var(--ep-hair);background:none;color:var(--ep-ink);text-align:left;font-family:inherit;cursor:pointer}
.ep-row:first-child{border-top:0}
:is(.ep-shell, .bizc-sheet-root) .ep-row-label{width:96px;flex:none;font-size:14px;color:var(--ep-mute)}
.ep-row-value{flex:1;min-width:0;font-size:15px;font-weight:500;color:var(--ep-ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ep-row-value.two{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;line-height:1.4}
.ep-row-value.ph{color:rgba(248,250,252,0.36)}
.ep-row-chev{color:var(--ep-dim);flex:none}
.ep-row:focus-visible,.ep-opt:focus-visible{outline:2px solid #F7931E;outline-offset:2px}
.bizc-sheet-done:disabled{opacity:.4;cursor:default}
.ep-two{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}
.ep-two .bizc-field{margin-top:0}
.ep-shown{font-size:13px;color:var(--ep-mute);margin-top:10px}
.ep-shown b{color:var(--ep-ink);font-weight:600}
.ep-toggle{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0 4px}
.ep-toggle b{display:block;font-size:15px;font-weight:600}
.ep-toggle span{display:block;font-size:12.5px;color:var(--ep-mute);margin-top:2px}
.ep-count{float:right;font-size:11px;color:var(--ep-dim);font-weight:600;letter-spacing:0;text-transform:none}
.ep-loc-field{width:100%;text-align:left;color:var(--ep-ink);font-family:inherit;cursor:pointer}
.ep-loc-value{display:flex;align-items:center;gap:8px;margin-top:6px;min-height:22px;font-size:16px;font-weight:600}
.ep-loc-value .ep-loc-input{margin-top:0;flex:1;min-width:0}
.ep-loc-ph{color:rgba(248,250,252,0.3);font-weight:500}
.ep-loc-chev{margin-left:auto;color:var(--ep-dim);flex:none}
.ep-loc-clear{background:none;border:0;color:var(--ep-dim);padding:0;display:flex;cursor:pointer}
.ep-at{color:var(--ep-dim)}
.ep-username{margin-top:14px}
.ep-username[data-soon=true]{opacity:.6}
.ep-available{margin-left:auto;display:inline-flex;align-items:center;gap:4px;color:#34D399;font-size:12.5px;font-weight:600;flex:none}
.ep-err{font-size:12.5px;color:#F87171;margin-top:8px}
.ep-bigta{display:block;width:100%;min-height:150px;margin-top:14px;padding:14px;background:var(--ep-card);border:1px solid var(--ep-hair);border-radius:16px;color:var(--ep-ink);font-size:15px;line-height:1.5;font-family:inherit;resize:none;outline:0;caret-color:var(--ep-ink)}
.ep-bigta:focus{border-color:rgba(248,250,252,0.32)}
.ep-bio-count{text-align:right;font-size:12.5px;color:var(--ep-dim);margin-top:8px}
.ep-opts{margin-top:8px}
.ep-opt{display:flex;align-items:center;justify-content:space-between;width:100%;padding:13px 0;border:0;border-top:1px solid var(--ep-hair);background:none;color:var(--ep-ink);font-size:15px;font-weight:600;font-family:inherit;cursor:pointer;text-align:left}
.ep-opt:first-child{border-top:0}
.ep-radio{width:20px;height:20px;border-radius:50%;border:1.5px solid rgba(255,255,255,0.3);box-sizing:border-box;flex:none}
.ep-opt[aria-checked=true] .ep-radio{border:6px solid var(--ep-ink)}
.ep-loc{display:flex;flex-direction:column}
.ep-loc .bizc-field:first-child{margin-top:14px}

/* EP3, isolated to the existing editor and shared sheets. */
:is(.ep-shell, .bizc-sheet-root) .ep-row{height:auto;border-radius:0;justify-content:flex-start;box-shadow:none;transition:none}
:is(.ep-shell, .bizc-sheet-root) .ep-row svg{width:18px;height:18px}
.ep-golf-mute,.ep-golf-source{color:var(--ep-mute)}
.ep-golf-source{font-size:13.5px;flex:none}
.ep-golf-index{display:flex;align-items:baseline;gap:10px;margin-top:14px;flex-wrap:wrap}
.ep-golf-index b{font-size:44px;font-weight:700;line-height:1;font-feature-settings:"kern" 1,"liga" 1}
.ep-golf-index span{font-size:13.5px;color:var(--ep-mute)}
.ep-golf-list{margin-top:14px}
.ep-golf-action{font-size:15px;font-weight:600;justify-content:space-between!important}
.ep-golf-connect{background:var(--ep-card);border:1px solid var(--ep-hair);border-radius:18px;padding:16px;margin-top:14px}
.ep-golf-connect b{display:block;font-size:16px;font-weight:600}
.ep-golf-connect p{font-size:13.5px;line-height:1.5;color:var(--ep-mute);margin-top:6px}
:is(.ep-shell, .bizc-sheet-root) .ep-golf-connect-button{height:40px;padding:0 18px;border-radius:999px;background:var(--ep-ink);color:var(--ep-canvas);font-size:14.5px;font-weight:600;margin-top:12px}
.ep-golf-or{display:flex;align-items:center;gap:10px;margin:16px 0 4px;font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--ep-dim);text-transform:uppercase}
.ep-golf-or::before,.ep-golf-or::after{content:"";flex:1;height:1px;background:var(--ep-hair)}
.ep-golf-hint{font-size:12.5px;color:var(--ep-dim);margin-top:8px;line-height:1.45}
:is(.ep-shell, .bizc-sheet-root) .ep-golf-search{display:block;width:100%;height:auto;text-align:left;border:1px solid var(--ep-hair);border-radius:16px;padding:12px 14px;margin-top:14px;background:var(--ep-card)}
.ep-golf-search-value{display:block;font-size:16px;font-weight:500;color:var(--ep-dim);margin-top:6px}
.ep-golf-club{display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid var(--ep-hair)}
.ep-golf-club:first-child{border-top:0}
.ep-golf-thumb{width:44px;height:44px;border-radius:10px;flex:none;background:var(--ep-inset);overflow:hidden;display:flex;align-items:center;justify-content:center;color:var(--ep-dim)}
.ep-golf-thumb img{width:100%;height:100%;object-fit:cover}
.ep-golf-club-text{flex:1;min-width:0}
.ep-golf-club-text b{display:block;font-size:15px;font-weight:600;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.ep-golf-club-text small{display:block;font-size:12.5px;color:var(--ep-mute);margin-top:2px}
.ep-golf-tick{color:var(--ep-success,#34D399)}
:is(.ep-shell, .bizc-sheet-root) .ep-golf-remove{color:var(--ep-dim);padding:0;background:none;border:0}
:is(.ep-shell, .bizc-sheet-root) .ep-golf-add{display:flex;width:100%;height:auto;align-items:center;justify-content:flex-start;gap:10px;font-size:15px;font-weight:600;padding:13px 0;border:0;border-top:1px solid var(--ep-hair);border-radius:0;color:var(--ep-ink)}
.ep-golf-add span{width:26px;height:26px;border-radius:50%;border:1px solid var(--ep-hair);display:flex;align-items:center;justify-content:center;color:var(--ep-mute)}

/* EP4 inline link inputs and existing EP2 radio inside a rows card. */
.ep-links-options{margin-top:14px}
.ep-links-hint{font-size:12.5px;color:var(--ep-dim);margin-top:8px;line-height:1.45}
.ep-privacy-hint{margin:8px 4px 0}
.ep-link-input-row{display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid var(--ep-hair);min-height:52px}
.ep-link-input-row:first-child{border-top:0}
.ep-link-input{flex:1;min-width:0;width:100%;background:none;border:0;outline:0;color:var(--ep-ink);font-size:15px;font-weight:500;font-family:inherit}
.ep-link-input::placeholder{color:var(--ep-dim)}
.ep-link-input:focus-visible{outline:1px solid var(--ep-hair);outline-offset:4px}
:is(.ep-shell, .bizc-sheet-root) .ep-link-remove{padding:0;width:24px;height:24px;background:none;border:0;color:var(--ep-dim)}
.ep-social-icon{width:30px;height:30px;border-radius:9px;background:var(--ep-inset);border:1px solid var(--ep-hair);display:flex;align-items:center;justify-content:center;flex:none}
.ep-social-input-row{gap:16px;padding:13px 0}
:is(.ep-shell, .bizc-sheet-root) .ep-links-options .ep-opt{height:auto;border-radius:0;justify-content:space-between;box-shadow:none;transition:none;padding:13px 0;color:var(--ep-ink);font-weight:600}
.ep-visibility-row{display:block;border-top:1px solid var(--ep-hair)}
.ep-shell .ep-visibility-row .ep-row{border-top:0}

/* EP5 completion card owns its two seams; all paint is local semantic material. */
.ep-shell{--ep-progress-missing:rgba(255,255,255,0.12);--ep-chip-ground:rgba(255,255,255,0.07);--ep-chip-hair:rgba(255,255,255,0.14)}
.ep-completion{background:var(--ep-card);border:1px solid var(--ep-hair);border-radius:18px;padding:14px 16px;margin-top:12px}
.ep-completion>b{font-size:15px;font-weight:600}
.ep-completion>p{font-size:13px;color:var(--ep-mute);margin-top:2px}
.ep-completion-bar{display:flex;gap:4px;margin-top:12px}
.ep-completion-bar i{flex:1;height:4px;border-radius:2px;background:var(--ep-progress-missing)}
.ep-completion-bar i[data-done=true]{background:var(--ep-ink)}
.ep-completion-chips{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}
.ep-shell .ep-completion-chip{height:32px;padding:0 12px;border-radius:999px;background:var(--ep-chip-ground);border:1px solid var(--ep-chip-hair);color:var(--ep-ink);font-size:13px;font-weight:600}
.ep-completion+.ep-group{margin-top:12px}

/* ST1: Settings-only placeholders/end card; deferred groups keep their controls. */
.ep-settings{--ep-settings-danger:#FF6B60}
.ep-settings .ep-row-value.ph{color:var(--ep-dim)}
.ep-settings-end{margin-top:28px}
.ep-shell .ep-settings-end .ep-row{justify-content:center}
.ep-settings-end .ep-row-value{flex:none;font-size:15px;font-weight:600}
.ep-settings-end .ep-settings-delete{color:var(--ep-settings-danger)}
.ep-settings-version{text-align:center;font-size:12px;color:var(--ep-dim);margin-top:22px}

/* ST2: handicap card only; canonical bizc switch stays unchanged elsewhere. */
.ep-settings{--st2-cell-hair:rgba(255,255,255,0.06);--st2-switch-off:rgba(255,255,255,0.16)}
.st2-handicap{background:var(--ep-card);border:1px solid var(--ep-hair);border-radius:18px;padding:16px 16px 0}
.ep-shell .st2-top{display:flex;align-items:flex-start;gap:12px;width:100%;height:auto;padding:0;border:0;border-radius:0;justify-content:flex-start;color:var(--ep-ink);text-align:left;font-family:inherit;box-shadow:none}
.st2-identity{display:block;min-width:0;flex:1}
.st2-name{display:block;font-size:17px;font-weight:700;letter-spacing:-0.01em;margin:0;line-height:normal}
.st2-status{display:block;font-size:12.5px;color:var(--ep-mute);white-space:nowrap;margin-top:3px;overflow:hidden;text-overflow:ellipsis}
.st2-manage{margin-left:auto;font-size:14px;font-weight:600;display:flex;align-items:center;gap:2px;flex:none;padding-top:2px}
.ep-shell .st2-manage svg{width:18px;height:18px;color:var(--ep-dim)}
.st2-figures{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));background:var(--ep-inset);border-radius:14px;margin-top:14px}
.st2-figure{padding:12px 12px 11px;border-left:1px solid var(--st2-cell-hair);min-width:0}
.st2-figure:first-child{border-left:0}
.st2-figure b{display:block;font-size:22px;font-weight:700;letter-spacing:-0.03em;font-feature-settings:"kern" 1,"liga" 1;color:var(--ep-ink)}
.st2-figure b[data-unknown=true]{color:var(--ep-dim)}
.st2-figure>span{display:block;font-size:9.5px;font-weight:800;letter-spacing:0.12em;text-transform:uppercase;color:var(--ep-dim);margin-top:3px}
.st2-line{font-size:13px;line-height:1.45;color:var(--ep-mute);margin:12px 0 0}
.st2-disconnected-line{margin-top:6px}
.ep-shell .st2-connect{display:inline-flex;height:40px;padding:0 18px;border-radius:999px;background:var(--ep-ink);color:var(--ep-canvas);font-size:14.5px;font-weight:600;margin-top:14px}
.st2-switch-row{display:flex;align-items:center;gap:12px;min-height:52px;padding:13px 0;border-top:1px solid var(--ep-hair);margin-top:12px}
.st2-disconnected-switch{margin-top:16px}
.st2-switch-copy{flex:1;min-width:0;font-size:15px;font-weight:500;color:var(--ep-ink)}
.st2-switch-copy small{display:block;font-size:12.5px;color:var(--ep-dim);font-weight:400;margin-top:2px}
:is(.ep-shell, .bizc-sheet-root) .st2-switch{position:relative;flex:none;width:44px;height:26px;padding:0;border:0;border-radius:999px;background:var(--st2-switch-off);box-shadow:none}
:is(.ep-shell, .bizc-sheet-root) .st2-switch[aria-checked=true]{background:var(--ep-ink)}
:is(.ep-shell, .bizc-sheet-root) .st2-switch i{position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:var(--ep-ink)}
:is(.ep-shell, .bizc-sheet-root) .st2-switch[aria-checked=true] i{left:21px;background:var(--ep-canvas)}

