        right: 0,
        bottom: 0,
        background: A.CANVAS,
        borderTop: '1px solid rgba(255,255,255,0.08)',
        padding: '12px 16px calc(16px + env(safe-area-inset-bottom, 0px))',
        textAlign: 'center',
        zIndex: 20,
      }}
    >
      <div style={{ maxWidth: 520, margin: '0 auto' }}>
        <p style={{ margin: 0, fontSize: 13.5, color: 'rgba(248,250,252,0.62)' }}>
          {t('findPeople.inviteLine', { defaultValue: "Invite friends who aren't on clbhouz" })}
        </p>
        <button
          type="button"
          onClick={() => invite?.openInviteSheet('find_people')}
          style={{
            width: '100%',
            height: 44,
            marginTop: 10,
            borderRadius: 999,
            border: 'none',
            background: A.INK,
            color: A.CANVAS,
            fontSize: 15,
            fontWeight: 600,
            fontFamily: ROW_FONT,
            cursor: 'pointer',
          }}
        >
          {t('findPeople.inviteAction', { defaultValue: 'Invite friends' })}
        </button>
      </div>
    </div>
  );
}

